<?php use App\Core\View; ?>
<div class="page-header"><div><p class="eyebrow">QR·공유</p><h1><?= View::e($item['title']) ?></h1><p class="muted">게시 중인 초대장의 공유 도구입니다.</p></div><a class="button secondary" href="/admin/invitations">목록</a></div>
<section class="panel share-panel">
<div class="qr-card"><img src="<?= View::e($qrUrl) ?>" width="320" height="320" alt="<?= View::e($item['title']) ?> QR 코드" referrerpolicy="no-referrer"><p class="muted">QR 코드를 인쇄물이나 안내 화면에 사용하세요.</p></div>
<div class="share-tools"><label>공개 초대장 주소<input id="public-url" type="url" readonly value="<?= View::e($publicUrl) ?>"></label><div class="actions"><button class="primary" type="button" id="copy-url">주소 복사</button><a class="button secondary" target="_blank" rel="noopener" href="<?= View::e($publicUrl) ?>">초대장 보기</a><a class="button secondary" href="sms:?&body=<?= rawurlencode($item['title'].' '.$publicUrl) ?>">문자로 공유</a><a class="button secondary" href="mailto:?subject=<?= rawurlencode($item['title']) ?>&body=<?= rawurlencode($publicUrl) ?>">이메일 공유</a><a class="button secondary" href="<?= View::e($qrUrl) ?>" download="invitation-qr.png" referrerpolicy="no-referrer">QR 저장</a></div><p id="copy-result" class="muted" role="status"></p><p class="muted">현재 QR은 공개 초대장 주소만 외부 생성 서비스에 전달합니다.</p></div>
</section>
<script>document.getElementById('copy-url')?.addEventListener('click',async()=>{const input=document.getElementById('public-url');const result=document.getElementById('copy-result');try{await navigator.clipboard.writeText(input.value);result.textContent='주소를 복사했습니다.';}catch(e){input.select();document.execCommand('copy');result.textContent='주소를 복사했습니다.';}});</script>